    { text: "اللهم إنا نسألك من خير ما سألك منه عبدك ونبيك محمد ﷺ، ونعوذ بك من شر ما استعاذ منه عبدك ونبيك محمد ﷺ", source: "دعاء جامع مأثور" },
    { text: "اللهم أصلح لنا ديننا الذي هو عصمة أمرنا، وأصلح لنا دنيانا التي فيها معاشنا، وأصلح لنا آخرتنا التي فيها معادنا", source: "دعاء جامع" },
    { text: "اللهم اجعل الحياة زيادة لنا في كل خير، واجعل الموت راحة لنا من كل شر", source: "صحيح مسلم" },
    { text: "اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت، وتولنا فيمن توليت، وبارك لنا فيما أعطيت، وقنا واصرف عنا شر ما قضيت", source: "دعاء القنوت المأثور" },
    { text: "اللهم إنا نستعينك ونستغفرك ونستهديك ونؤمن بك ونتوكل عليك ونثني عليك الخير كله، نشكرك ولا نكفرك", source: "دعاء القنوت المأثور" },
    { text: "اللهم إياك نعبد، ولك نصلي ونسجد، وإليك نسعى ونحفد، نرجو رحمتك ونخشى عذابك إن عذابك الجد بالكفار ملحق", source: "دعاء القنوت المأثور" },
    { text: "اللهم إنا نسألك إيماناً يباشر قلوبنا، ويقيناً صادقاً حتى نعلم أنه لن يصيبنا إلا ما كتبت لنا، والرضا بما قسمت لنا", source: "دعاء الإيمان واليقين" },
    { text: "اللهم آت نفوسنا تقواها، وزكها أنت خير من زكاها، أنت وليها ومولاها", source: "دعاء تزكية النفس" },
    { text: "اللهم أعنا على ذكرك وشكرك وحسن عبادتك وتلاوة كتابك والعمل بسنة نبيك ﷺ", source: "دعاء الطاعة والعبادة" },
    { text: "اللهم حبب إلينا الإيمان وزينه في قلوبنا، وكره إلينا الكفر والفسوق والعصيان، واجعلنا من عبادك الراشدين", source: "دعاء الإيمان والاستقامة" },
    { text: "اللهم ارزقنا حبك، وحب من يحبك، وحب كل عمل يقربنا إلى حبك", source: "جامع الترمذي" },
    { text: "اللهم اجعل حبك أحب إلينا من أنفسنا وأهلينا وأموالنا ومن الماء البارد على الظمأ", source: "دعاء محبة الله" },
    { text: "اللهم اشرح صدورنا للإسلام، ونور قلوبنا بالإيمان، واستعمل أبداننا في طاعتك يا رحمن", source: "دعاء الانشراح والطاعة" },
    { text: "اللهم طهر قلوبنا من الغل والحقد والحسد والنفاق، وطهر ألسنتنا من الكذب والغيبة والنميمة", source: "دعاء طهارة القلب واللسان" },
    { text: "اللهم اغفر لنا ذنوبنا كلها، دقها وجلها، أولها وآخرها، علانيتها وسرها، ما علمنا منها وما لم نعلم", source: "دعاء المغفرة الشاملة" },
    { text: "اللهم إنا ظلمنا أنفسنا ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لنا مغفرة من عندك وارحمنا إنك أنت الغفور الرحيم", source: "دعاء الاستغفار" },
    { text: "اللهم تب علينا توبة نصوحاً تطهر بها قلوبنا، وتغسل بها حوبتنا، وتستر بها عوراتنا، وتقبل بها أعمالنا", source: "دعاء التوبة النصوح" },
    { text: "اللهم إنك عفو كريم تحب العفو فاعف عنا، اللهم إنك عفو تحب العفو فاعف عنا", source: "دعاء العفو وليلة القدر" },
    { text: "اللهم ارزقنا علمًا نافعًا، ورزقًا واسعًا حلالًا طيبًا، وعملًا صالحًا متقبلًا", source: "دعاء العلم والرزق" },
    { text: "اللهم بارك لنا في أرزاقنا وأوقاتنا وأعمارنا وأهلينا وذرياتنا وأعمالنا", source: "دعاء البركة الشاملة" },
    { text: "اللهم قنعنا بما رزقتنا، وبارك لنا فيه، واخلف علينا كل غائبة لنا بخير", source: "دعاء القناعة والبركة" },
    { text: "اللهم افتح لنا أبواب رحمتك، ويسر لنا أسباب فضلك، وأغننا بحلالك عن حرامك وبفضلك عمن سواك", source: "دعاء الرزق والغنى بالله" },
    { text: "اللهم لا تكلنا إلى أنفسنا طرفة عين، ولا إلى أحد من خلقك، وتول أمرنا كله بلطفك وتوفيقك", source: "دعاء التوكل والتفويض" },
    { text: "اللهم دبر لنا فإنا لا نحسن التدبير، واختر لنا فإنا لا نحسن الاختيار، ويسر لنا الخير حيث كان", source: "دعاء الخيرة والتدبير" },
    { text: "اللهم ألهمنا رشدنا وأعذنا من شرور أنفسنا ومن سيئات أعمالنا", source: "دعاء الرشد والسلامة" },
    { text: "اللهم ارزقنا حسن التوكل عليك، وصدق اللجوء إليك، وحسن الظن بك، والرضا بقضائك", source: "دعاء حسن الظن بالله" },
    { text: "اللهم وفقنا لما تحب وترضى، وخذ بنواصينا للبر والتقوى، ومن العمل ما ترضى", source: "دعاء التوفيق للبر" },
    { text: "اللهم إنا نسألك لساناً ذاكراً، وقلباً شاكراً، وبدناً على البلاء صابراً", source: "دعاء الذكر والشكر والصبر" },
    { text: "اللهم اجعلنا من عبادك المخلصين المخلصين، المتقين الأبرار، السعداء في الدنيا والآخرة", source: "دعاء الصلاح والسعادة" },
    { text: "اللهم أصلح لنا شأننا كله، وبارك لنا في خطانا، واجعلنا مفاتيح للخير مغاليق للشر", source: "دعاء النفع والخير" },
    { text: "اللهم اهدنا لأحسن الأخلاق لا يهدي لأحسنها إلا أنت، واصرف عنا سيئها لا يصرف عنا سيئها إلا أنت", source: "صحيح مسلم" },
    { text: "اللهم إنا نعوذ بك من منكرات الأخلاق والأعمال والأهواء والأدواء", source: "دعاء الاستعاذة من الشرور" },
    { text: "اللهم عافنا في أبداننا، وعافنا في أسماعنا، وعافنا في أبصارنا، لا إله إلا أنت", source: "دعاء العافية" },
    { text: "اللهم إنا نسألك العفو والعافية والمعافاة الدائمة في الدين والدنيا والآخرة", source: "دعاء العافية الدائمة" },
    { text: "اللهم احفظنا بالإسلام قائمين، واحفظنا بالإسلام قاعدين، واحفظنا بالإسلام راقدين، ولا تشمت بنا عدواً ولا حاسداً", source: "المستدرك للحاكم" },
    { text: "اللهم استرنا فوق الأرض، وتحت الأرض، ويوم العرض عليك يا أرحم الراحمين", source: "دعاء الستر" },
    { text: "اللهم لا تحرمنا خير ما عندك بسوء ما عندنا، وعاملنا بما أنت أهله ولا تعاملنا بما نحن أهله", source: "دعاء الرجاء" },
    { text: "اللهم أعتق رقابنا ورقاب آبائنا وأمهاتنا وأهلينا من النار", source: "دعاء العتق من النار" },
    { text: "اللهم اغفر لوالدينا أحياءً وأمواتاً، وارفع درجاتهم في عليين، واجمعنا بهم في جنات النعيم", source: "دعاء البر بالوالدين" },
    { text: "اللهم ارحم موتى المسلمين، وعاف مبتلى المسلمين، واشف مرضى المسلمين، وفك أسرى المسلمين", source: "دعاء لأمة الإسلام" },
    { text: "اللهم بارك في أولادنا وذرياتنا، واحفظهم من كل سوء، واجعلهم من حفظة كتابك والعاملين به", source: "دعاء للذرية" },
    { text: "اللهم ألف بين قلوبنا، وأصلح ذات بيننا، واهدنا سبل السلام، ونجنا من الظلمات إلى النور", source: "المستدرك للحاكم" },
    { text: "اللهم ارزقنا صحبة الأخيار، ومجالسة العلماء الأبرار، وأبعد عنا رفقاء السوء والأشرار", source: "دعاء الصحبة الصالحة" },
    { text: "اللهم ارزقنا لذة القرب منك، والأنس بذكرك، والخشوع في صلاتك، والتدبر لكتابك", source: "دعاء الأنس بالله" },
    { text: "اللهم اجعل القرآن العظيم ربيع قلوبنا، ونور أبصارنا، وشفاء صدورنا، وهادينا إلى جناتك جنات النعيم", source: "دعاء القرآن الكريم" },
    { text: "اللهم علمنا ما ينفعنا، وانفعنا بما علمتنا، وزدنا علماً وفقهاً في الدين", source: "دعاء طلب العلم" },
    { text: "اللهم ارزقنا حج بيتك الحرام وزيارة مسجد نبيك ﷺ مرات ومرات متقبلة مبرورة", source: "دعاء الحج والعمرة" },
    { text: "اللهم انصر الإسلام وأعز المسلمين، وأعل بفضلك كلمة الحق والدين، واخذل من خذل الدين", source: "دعاء نصرة الإسلام" },
    { text: "اللهم احفظ بلادنا وبلاد المسلمين من الفتن والمحن ما ظهر منها وما بطن", source: "دعاء حفظ الأوطان" },
    { text: "اللهم آمن روعاتنا واستر عوراتنا واحفظنا من بين أيدينا ومن خلفنا وعن أيماننا وعن شمائلنا ومن فوقنا", source: "دعاء الحفظ والتحصين" },
    { text: "اللهم بارك لنا في رجب وشعبان وبلغنا رمضان، وأعنا فيه على الصيام والقيام وغض البصر وحفظ اللسان", source: "دعاء المواسم المباركة" },
    { text: "اللهم تقبل منا إنك أنت السميع العليم، وتب علينا إنك أنت التواب الرحيم", source: "دعاء القبول" },
    { text: "اللهم اجعل خير أعمارنا أواخرها، وخير أعمالنا خواتيمها، وخير أيامنا يوم نلقاك فيه", source: "دعاء حسن الخاتمة" },
    { text: "اللهم توفنا وأنت راضٍ عنا غير غضبان، وابعثنا آمنين مطمئنين مع الذين أنعمت عليهم", source: "دعاء الوفاة على الإيمان" },
    { text: "اللهم هون علينا سكرات الموت، وثبتنا عند سؤال الملكين، واجعل قبورنا روضة من رياض الجنة", source: "دعاء القبر" },
    { text: "اللهم أظلنا في ظلك يوم لا ظل إلا ظلك، وأمنا يوم الفزع الأكبر، وتقبل أعمالنا برحمتك", source: "دعاء يوم القيامة" },
    { text: "اللهم أدخلنا الجنة بسلام بغير حساب ولا سابقة عذاب، ومتعنا بالنظر إلى وجهك الكريم", source: "دعاء الفردوس" },
    { text: "اللهم ارزقنا الفردوس الأعلى من الجنة ومرافقة نبينا محمد ﷺ وشفاعته والحوض المورود", source: "دعاء الفردوس الأعلى" },
    { text: "اللهم اشف مرضانا ومرضى المسلمين شفاء لا يغادر سقماً، وألبسهم ثوب الصحة والعافية", source: "دعاء الشفاء" },
    { text: "اللهم اقض الدين عن المدينين، وفرج هم المهمومين، ونفس كرب المكروبين، ويسر أمور المؤمنين", source: "دعاء تفريج كرب المسلمين" },
    { text: "اللهم اجعلنا ممن يستمعون القول فيتبعون أحسنه، وممن يرضى عنهم ويدخلهم برحمتك في عبادك الصالحين", source: "دعاء الاتباع الصالح" },
    { text: "اللهم ارزقنا الإخلاص في القول والعمل، والصدق في السر والعلن، والبركة في كل أمر", source: "دعاء الإخلاص" },
    { text: "اللهم صل وسلم وبارك على سيدنا محمد عدد ما ذكره الذاكرون وغفل عن ذكره الغافلون", source: "الصلاة على النبي ﷺ" },
    { text: "سبحان ربك رب العزة عما يصفون، وسلام على المرسلين، والحمد لله رب العالمين", source: "خاتمة الدعاء" }
